// A single call covering every sheet in a large workbook can run long
// enough to trip n8n's gateway timeout (502), so the caller pages through
// sheets chunk_size at a time via offset/limit in the webhook body.
const body = $('Webhook').first().json.body;
const offset = Number(body.offset ?? 0);
const limit = Number(body.limit ?? 1000);
return $input.all().slice(offset, offset + limit);

const output = [];
for (const item of $input.all()) {
  const sheet = item.json.data.address.split('!')[0].replace(/^'|'$/g, '');
  const rows = item.json.data.values ?? [];
  for (const row of rows) {
    const dtc = row[0];
    if (!dtc) continue; // skips the leftover sub-header row and blank padding rows within the fixed A3:H5000 range
    output.push({
      json: {
        sheet,
        dtc,
        description: row[1],
        warning_light: row[2],
        warning_message: row[3],
        limp_home: row[4],
        fail_safe: row[5],
        grade: row[6],
        grading_background: row[7],
      },
    });
  }
}
return output;

// Sheets that are known non-diagnostic artifacts (default Excel names,
// leftover duplicate-sheet copies, or roll-up/summary tabs) rather than real
// System data. Dropped here, before mapping/AI review, so they never turn
// into an 'unmapped sheet' alert or duplicate rows in the output.
const IGNORE_PATTERNS = [
  /^Sheet\d+$/i, // default Excel sheet names: Sheet1, Sheet2, ...
  /^Total(\s*\(\d+\))?$/i, // roll-up/summary tabs: Total, Total (2), ...
  /\s\(\d+\)$/, // any sheet ending in a copy suffix: "X (2)", "X (3)"
];

// Known documentation/legend sheets that describe grading rules or other
// metadata rather than listing a real System's DTCs. Pattern-matching a name
// like this would be too fragile, so these are tracked as an explicit,
// case-insensitive exact-name list -- add new ones here as they turn up.
const IGNORE_EXACT_NAMES = new Set([
  "dtc grade criteria",
]);

